"""Viseme vectors (ADR-003, migration batch 1; not part of the shared companion contract), generated by MOSAIC's own
tools/behavior_plan_from_audio.py, so that AIJADE's port (src/Aijade.Client/Companion/LipSync.cs) shapes the mouth from
a reply's aligned characters as MOSAIC's renderer client is told to.

MOSAIC is read-only from this repository: its module is loaded from its file and no bytecode is written. Its aligned
tracks use numpy only for a zero vector of five and for elementwise addition and division, and numpy is not installed
here, so a five-element stand-in provides those three operations. Python floats are IEEE doubles like numpy's float64,
and the additions run in the same order, so the numbers are the same:

    python3 -B -I configs/companion/generate_viseme_vectors.py \
        <MOSAIC>/tools/behavior_plan_from_audio.py configs/companion/viseme-vectors.json

The cases are rows as MOSAIC's align server (tools/align_server.py) returns them: each Chinese character with its start
and end in seconds and its strict pinyin initial and final. They cover a plain syllable, glides with two and three vowel
shapes (with shares that round half to even), ü and er, b/p/m closures that run into one another, f's half closure, a
syllabic nasal without a vowel, an unknown final, a character without an initial, and characters past the end of the
audio. The file records the source file's SHA-256 and the date read.
"""
import hashlib, importlib.util, json, sys, time, types
sys.dont_write_bytecode = True
src, out = sys.argv[1], sys.argv[2]


class Five(list):
    """numpy.zeros(5) as far as aligned_tracks uses it: item assignment, elementwise + (also 0 + v, for sum) and / n."""
    def __add__(self, other):
        return Five(a + b for a, b in zip(self, other))

    def __radd__(self, other):
        return Five(other + a for a in self)

    def __truediv__(self, n):
        return Five(a / n for a in self)


numpy = types.ModuleType("numpy")
numpy.zeros = lambda n: Five([0.0] * n)
sys.modules["numpy"] = numpy
spec = importlib.util.spec_from_file_location("behavior_plan_from_audio", src)
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)


def rows(*items):
    return [dict(char=c, start_s=s, end_s=e, initial=i, final=f) for c, s, e, i, f in items]


cases = [
    ("你好呀", 60, rows(("你", .1, .3, "n", "i"), ("好", .3, .55, "h", "ao"), ("呀", .55, .8, "", "ia"))),
    ("小快", 30, rows(("小", 0., 1 / 6, "x", "iao"), ("快", 1 / 6, 1 / 3, "k", "uai"))),
    ("妈妈不怕", 60, rows(("妈", .05, .2, "m", "a"), ("妈", .2, .35, "m", "a"), ("不", .35, .5, "b", "u"), ("怕", .62, .8, "p", "a"))),
    ("飞机", 45, rows(("飞", .1, .35, "f", "ei"), ("机", .35, .6, "j", "i"))),
    ("学习女儿", 75, rows(("学", 0., .3, "x", "ve"), ("习", .3, .5, "x", "i"), ("女", .5, .8, "n", "v"), ("儿", .8, 1.1, "", "er"))),
    ("月亮", 50, rows(("月", .2, .45, "", "ve"), ("亮", .45, .7, "l", "iang"))),
    ("嗯啊", 50, rows(("嗯", .1, .4, "", "n"), ("啊", .45, .7, "", "a"))),
    ("知", 30, rows(("知", .1, .4, "zh", "xyz"))),
    ("我们", 40, rows(("我", .1, .4, "", "uo"), ("们", .5, .75, "m", "en"))),
    ("超出", 40, rows(("说", .4, .7, "sh", "uo"), ("吗", .7, 1.0, "m", "a"), ("吧", 1.1, 1.3, "b", "a"))),
]
vectors = []
for text, frames, items in cases:
    track, lips = m.aligned_tracks(items, frames)
    vectors.append(dict(text=text, frames=frames, characters=[
        dict(char=r["char"], startS=r["start_s"], endS=r["end_s"], initial=r["initial"], final=r["final"]) for r in items],
        vowels=[None if w is None else list(w) for w in track], lips=[dict(frame=f, value=v) for f, _, v in lips]))

with open(src, "rb") as f:
    digest = hashlib.sha256(f.read()).hexdigest()
doc = dict(
    note="Generated by configs/companion/generate_viseme_vectors.py from MOSAIC's tools/behavior_plan_from_audio.py "
         "(aligned_tracks); AIJADE's port is src/Aijade.Client/Companion/LipSync.cs (ADR-003).",
    source=dict(file="tools/behavior_plan_from_audio.py", sha256=digest, read=time.strftime("%Y-%m-%d")),
    constants=dict(frameHz=m.FRAME_HZ, closureBeforeS=m.CLOSURE_BEFORE_S, closureAfterS=m.CLOSURE_AFTER_S,
                   lipInitials=m.LIP_INITIALS,
                   finalShapes={k: [dict(vowels=v, share=s) for v, s in shapes] for k, shapes in m.FINAL_SHAPES.items()}),
    cases=vectors)
with open(out, "w", encoding="utf-8") as f:
    json.dump(doc, f, ensure_ascii=False, indent=1)
    f.write("\n")
print(len(vectors), "cases")
